{
  "finding_id": "F-080",
  "finding_sha256": "9f2f9ac8cfec2dc5a576e42a87e5f6adb75fd62cb284d503ad08df6041022285",
  "source_md_sha256": "2efe94fab36eeee0e182e35fce46783b258bfccade2b564b0bf449628cc51f92",
  "context_sha256": null,
  "claims": [
    {
      "claim_id": "F-080-C1",
      "claim": "В узле «Установка шкафов автоматики и управления» высота шкафа ШАУВ-1-К6-ПЧ обозначена размером 1400 мм.",
      "status": "supported",
      "reason": "Размер 1400 нанесён между выносными линиями от верхней и нижней границ изображённого шкафа.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.455, 0.429, 0.714, 0.765],
          "observation": "Надпись на шкафу — ШАУВ-1-К6-ПЧ. Вертикальный размер 1400 справа от размерной линии связывает верх и низ этого шкафа."
        }
      ]
    },
    {
      "claim_id": "F-080-C2",
      "claim": "Расстояние от показанного уровня пола до низа шкафа обозначено размером 1000 мм.",
      "status": "supported",
      "reason": "Нижний участок вертикальной цепи ограничен выносной линией от низа шкафа и линией верхней поверхности показанного пола.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.451, 0.737, 0.716, 0.864],
          "observation": "Размер 1000 расположен между отметкой низа шкафа и верхней горизонтальной границей конструкции пола."
        }
      ]
    },
    {
      "claim_id": "F-080-C3",
      "claim": "Общий размер от того же уровня пола до верха шкафа обозначен как 1800 мм.",
      "status": "supported",
      "reason": "Внешняя вертикальная размерная линия имеет крайние отметки на тех же уровнях, что верх шкафа и нижний конец размера 1000.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.431, 0.428, 0.716, 0.862],
          "observation": "Внешний размер 1800 проходит от общей верхней выносной линии у верха шкафа до общей нижней линии на уровне пола."
        }
      ]
    },
    {
      "claim_id": "F-080-C4",
      "claim": "Вертикальная размерная цепь установки шкафа противоречива на 600 мм.",
      "status": "supported",
      "reason": "Для одного изображённого шкафа последовательные размеры составляют 1400 + 1000 = 2400 мм. Общий размер между теми же крайними уровнями указан как 1800 мм. Расхождение: 2400 − 1800 = 600 мм. Это противоречие размерных обозначений; фактические размеры установленного оборудования изображением не установлены.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.429, 0.426, 0.718, 0.865],
          "observation": "У шкафа ШАУВ-1-К6-ПЧ размер 1400 связывает верх и низ, размер 1000 продолжает цепь от низа до пола, а размер 1800 соединяет верх шкафа с тем же уровнем пола."
        }
      ]
    },
    {
      "claim_id": "F-080-C5",
      "claim": "Противоречие создаёт неоднозначную высоту установки шкафа при монтаже.",
      "status": "supported",
      "reason": "Все три указания одновременно выполнить невозможно. При высоте шкафа 1400 мм общий размер 1800 мм подразумевает привязку низа 400 мм, тогда как непосредственно указано 1000 мм. Риск неоднозначного выбора монтажной привязки подтверждён; совершённая ошибка монтажа не установлена.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.429, 0.426, 0.718, 0.865],
          "observation": "Общий размер 1800, высота 1400 и нижняя привязка 1000 относятся к одной вертикальной цепи одного шкафа."
        }
      ]
    },
    {
      "claim_id": "F-080-C6",
      "claim": "Следует уточнить проектную высоту установки и габарит шкафа, согласовав общий размер с высотой шкафа и привязкой его низа к полу.",
      "status": "supported",
      "reason": "Рекомендация непосредственно устраняет подтверждённое противоречие. Из изображения нельзя определить, какое из трёх числовых обозначений следует исправить.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.429, 0.426, 0.718, 0.865],
          "observation": "На изображении одновременно приведены несовместимые вертикальные размеры 1400, 1000 и 1800; указания о приоритете одного из них в данном узле нет."
        }
      ]
    },
    {
      "claim_id": "F-080-C7",
      "claim": "Утверждение сохранено в F-036 совместно с G-102.",
      "status": "needs_data",
      "reason": "Это утверждение о содержании других записей отчёта. Представленный чертёж и его штамп не подтверждают объединение или сохранение замечаний.",
      "evidence": [],
      "missing_data": [
        "Содержимое записей F-036 и G-102 либо запись об их объединении с рассматриваемым утверждением."
      ]
    },
    {
      "claim_id": "F-080-C8",
      "claim": "Замечание имеет категорию серьёзности «ЭКСПЛУАТАЦИОННОЕ».",
      "status": "needs_data",
      "reason": "Изображение подтверждает противоречие монтажных размеров, но не устанавливает критерии категории серьёзности или конкретные последствия для эксплуатации.",
      "evidence": [
        {
          "type": "image",
          "block_id": "blk_d52bf811660e42b59acdce0038f9fbf0",
          "image_sha256": "42c7d8b05562c4c461752bf37d98233d9a519a4530360dd8f160494b4500ce95",
          "bbox_norm_xyxy": [0.429, 0.426, 0.718, 0.865],
          "observation": "Показан узел установки шкафа с противоречивой размерной цепью; эксплуатационные последствия и категория серьёзности на нём не указаны."
        }
      ],
      "missing_data": [
        "Критерии отнесения замечаний к категории «ЭКСПЛУАТАЦИОННОЕ».",
        "Обоснование применения этих критериев к выявленной неоднозначности высоты установки."
      ]
    }
  ]
}
